export type YogaDetail = {
    /**
     * Glossary id (lowercase, kebab-case) matching an entry in the 301-entry planetary-yoga catalog. Use with GET /yoga/{id} to retrieve the full glossary text.
     */
    id: string;
    /**
     * Classical Sanskrit name of the yoga as referenced in BPHS (Brihat Parashara Hora Shastra), Phaladeepika, and B.V. Raman *Three Hundred Important Combinations*.
     */
    name: string;
    /**
     * Brief classical formation rule. Identifies the planetary placement, lordship, dignity, aspect pattern, sign modality, or whole-chart bhava distribution required for the yoga to form.
     */
    description: string;
    /**
     * Classical phala (life-effect) description of the yoga when present, sourced from the parashari and phaladeepika tradition.
     */
    result: string;
    /**
     * Overall nature. Auspicious yogas (Pancha Mahapurusha, Gajakesari) bestow benefits; inauspicious yogas (Kemadruma) indicate challenges; Both denotes context-dependent effects.
     */
    quality: 'Positive' | 'Negative' | 'Both';
    /**
     * Nabhasa family this yoga belongs to, present only on the 32 Nabhasa distribution yogas: asraya (3, sign modality), dala (2, benefic or malefic kendra tenancy), akriti (20, bhava shape) and sankhya (7, count of occupied rasis). Absent on every other glossary row, which is most of the catalog, since those are single-combination yogas outside the Nabhasa scheme. Group or filter the catalog on this key; it is never translated.
     */
    family?: 'classical' | 'asraya' | 'dala' | 'akriti' | 'sankhya';
};

export type YogaDetectResponse = {
    /**
     * Array of 48 detected yogas, always the full set so a caller can render absent verdicts too. Every entry carries a `present` boolean and a `quality` (Positive, Negative, or Both = auspicious, inauspicious, or context-dependent); filter on present === true for active yogas. Evidence text names the rule that triggered or failed, or the precedence norm that outranked it.
     */
    yogas: Array<{
        /**
         * Glossary id (lowercase, kebab-case) matching an entry in the 301-entry planetary-yoga catalog. Use with GET /yoga/{id} to retrieve the full glossary text.
         */
        id: string;
        /**
         * Classical Sanskrit name of the yoga as referenced in BPHS (Brihat Parashara Hora Shastra), Phaladeepika, and B.V. Raman *Three Hundred Important Combinations*.
         */
        name: string;
        /**
         * Brief classical formation rule. Identifies the planetary placement, lordship, dignity, aspect pattern, sign modality, or whole-chart bhava distribution required for the yoga to form.
         */
        description: string;
        /**
         * Classical phala (life-effect) description of the yoga when present, sourced from the parashari and phaladeepika tradition.
         */
        result: string;
        /**
         * Overall nature. Auspicious yogas (Pancha Mahapurusha, Gajakesari) bestow benefits; inauspicious yogas (Kemadruma) indicate challenges; Both denotes context-dependent effects.
         */
        quality: 'Positive' | 'Negative' | 'Both';
        /**
         * Classical grouping, ALWAYS present on a detection verdict: one of the four Nabhasa families (asraya, dala, akriti, sankhya) or classical for the twelve single-combination yogas such as Gajakesari and the Pancha Mahapurusha. Group the verdict list on this key to render a Nabhasa result the way the tradition arranges it. Never translated, so grouping works identically under any lang.
         */
        family: 'classical' | 'asraya' | 'dala' | 'akriti' | 'sankhya';
        /**
         * True if every classical condition for the yoga is satisfied by the given chart. False means one of TWO different things: the rule failed, or the rule held and a stronger family outranked it. Read `suppressedBy` to tell those apart, which is exact and locale-independent; `evidence` says the same thing in English prose.
         */
        present: boolean;
        /**
         * Set ONLY when this yoga matched its own classical rule and was then silenced by a higher-ranking family, so `present` is false for a reason a practitioner reads very differently from a failed rule. Names the family that took precedence, under the four classical norms: Akriti outranks Asraya, and Akriti, Asraya and Dala each outrank Sankhya. Absent means the rule genuinely did not hold.
         */
        suppressedBy?: 'classical' | 'asraya' | 'dala' | 'akriti' | 'sankhya';
        /**
         * Human-readable rationale naming the specific rule that triggered or failed the detection, including planetary positions, dignity, kendradhipati status, lordship, malefic drishti, sign modality, or whole-chart bhava distribution. For a Nabhasa yoga that matched its own rule but was outranked, this names the precedence norm that silenced it, for example that an Akriti yoga outranks Asraya or that any other Nabhasa family suppresses Sankhya. English in every language, like the per-graha stateSource on POST /daily, because it is provenance to be checked against a text rather than display copy.
         */
        evidence?: string;
    }>;
    /**
     * The sidereal frame this response was computed in, so a cached or forwarded payload is self describing.
     */
    frame: {
        /**
         * Sidereal frame this chart was cast in, echoing the ayanamsa request field. "lahiri" when the field was omitted.
         */
        ayanamsa: string;
        /**
         * Degrees actually subtracted from every tropical longitude to produce this chart, read at the birth instant. Subtract it back to recover the tropical positions, or compare it against your reference software to confirm you are in the same frame before chasing a placement difference.
         */
        ayanamsaDegrees: number;
    };
    /**
     * Count of yogas where present === true in this chart. Range 0-48, though real charts sit in the low single digits: the Nabhasa families are mutually constrained by the precedence norms, and most shape yogas are rare.
     */
    total: number;
    /**
     * Echo of the resolved birth data used for detection. Timezone is the numeric offset that the chart engine consumed (IANA names are resolved upstream).
     */
    birthDetails: {
        /**
         * Birth date the kundli was cast for, YYYY-MM-DD, echoed back from the request.
         */
        date: string;
        /**
         * Birth time the kundli was cast for, 24-hour HH:MM:SS, echoed back from the request. Lagna moves roughly one rashi every two hours, so this is what pins the bhava-dependent yogas.
         */
        time: string;
        /**
         * Birth latitude in decimal degrees, echoed back from the request. Feeds the local sidereal time behind the Lagna.
         */
        latitude: number;
        /**
         * Birth longitude in decimal degrees, echoed back from the request. East is positive, west is negative.
         */
        longitude: number;
        /**
         * Numeric UTC offset in decimal hours that the chart engine actually consumed. An IANA name sent on the request is resolved to its DST-correct offset upstream, so this is always a number.
         */
        timezone: number;
    };
};

