export type PostAstrologyHousesData = {
    body?: {
        /**
         * Birth date in YYYY-MM-DD format. Date is critical for house cusp calculations as it determines planetary positions used in some house systems.
         */
        date: string;
        /**
         * Birth time in 24-hour HH:MM:SS format. Time is ESSENTIAL for accurate house cusps, and even minutes matter. The Ascendant (1st house cusp) changes roughly every 4 minutes. Without accurate time, house placements will be incorrect.
         */
        time: string;
        /**
         * Birth location latitude in decimal degrees (-90 to 90). Location determines the local horizon and meridian, which are fundamental to house division. Higher latitudes cause more distortion in time-based systems like Placidus.
         */
        latitude: number;
        /**
         * Birth location longitude in decimal degrees (-180 to 180). Affects local time and horizon calculations for house cusps.
         */
        longitude: number;
        /**
         * Decimal hours from UTC (e.g. -5 for EST, 5.5 for IST, 9 for JST) OR IANA name (e.g. "America/New_York"). IANA resolved to the DST-correct offset for the chart date.
         */
        timezone: number | string;
        /**
         * House system for dividing ecliptic into 12 houses. Placidus (most popular) uses time, Whole Sign (ancient) uses signs, Equal divides from Ascendant. Use "all" to compare all 4 systems side-by-side for educational purposes.
         */
        houseSystem?: 'placidus' | 'whole-sign' | 'equal' | 'koch' | 'all';
    };
    path?: never;
    query?: {
        /**
         * Response language (BCP 47). Supported: en, tr, de, es, hi, pt, fr, ru, zh-Hans, zh-Hant. Defaults to en. Coverage varies by domain, and a field with no translation in the requested language returns English.
         */
        lang?: 'en' | 'tr' | 'de' | 'es' | 'hi' | 'pt' | 'fr' | 'ru' | 'zh-Hans' | 'zh-Hant';
    };
    url: '/astrology/houses';
};

